package com.example.examplemod.net;

import com.example.examplemod.ExampleMod;
import io.netty.buffer.ByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;

public record UseWandPayload(int x, int y, int z) implements CustomPacketPayload {

    public static final Type<UseWandPayload> TYPE =
            new Type<>(ResourceLocation.fromNamespaceAndPath(ExampleMod.MODID, "use_wand"));

    public static final StreamCodec<ByteBuf, UseWandPayload> CODEC = StreamCodec.composite(
            ByteBufCodecs.VAR_INT, UseWandPayload::x,
            ByteBufCodecs.VAR_INT, UseWandPayload::y,
            ByteBufCodecs.VAR_INT, UseWandPayload::z,
            UseWandPayload::new);

    @Override
    public Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }
}

