@Mod.EventBusSubscriber(modid = ExampleMod.MODID, bus = Mod.EventBusSubscriber.Bus.GAME)
public final class ModCommands {

    @SubscribeEvent
    public static void onRegisterCommands(RegisterCommandsEvent event) {
        CommandDispatcher<CommandSourceStack> dispatcher = event.getDispatcher();
        dispatcher.register(
                LiteralArgumentBuilder.<CommandSourceStack>literal("example")
                        .requires(source -> source.hasPermission(0))
                        .then(Commands.literal("hello")
                                .executes(context -> {
                                    context.getSource().sendSuccess(
                                            () -> Component.literal("Hello from examplemod!"), false);
                                    return com.mojang.brigadier.Command.SINGLE_SUCCESS;
                                })));
    }

    private ModCommands() {}
}

