import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.network.NetworkRegistry;
import net.minecraftforge.network.simple.SimpleChannel;

public final class Net {
    private static final String VERSION = "1";
    public static SimpleChannel CHANNEL = NetworkRegistry.newSimpleChannel(
            new ResourceLocation("examplemod", "main"),
            () -> VERSION, VERSION::equals, VERSION::equals);

    public record UseWand(int x, int y, int z) {}

    public static void register() {
        int id = 0;
        CHANNEL.messageBuilder(UseWand.class, id++)
                .encoder((msg, buf) -> { buf.writeVarInt(msg.x()); buf.writeVarInt(msg.y()); buf.writeVarInt(msg.z()); })
                .decoder(buf -> new UseWand(buf.readVarInt(), buf.readVarInt(), buf.readVarInt()))
                .handlerMainThread((msg, ctx) -> {
                    // server logic
                    ctx.get().setPacketHandled(true);
                })
                .add();
    }
}

