package com.example.examplemod.net;

import com.example.examplemod.ExampleMod;
import io.netty.buffer.ByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.Mod;
import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
import net.neoforged.neoforge.network.registration.PayloadRegistrar;

public record UseWandPayload(int x, int y, int z) implements CustomPacketPayload {

    public static final Type<UseWandPayload> TYPE =
            new Type<>(ResourceLocation.fromNamespaceAndPath(ExampleMod.MODID, "use_wand"));

    public static final StreamCodec<ByteBuf, UseWandPayload> CODEC = StreamCodec.composite(
            ByteBufCodecs.VAR_INT, UseWandPayload::x,
            ByteBufCodecs.VAR_INT, UseWandPayload::y,
            ByteBufCodecs.VAR_INT, UseWandPayload::z,
            UseWandPayload::new);

    @Override
    public Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }
}

// Registration (MOD bus) - second top-level class in the same file:
@Mod.EventBusSubscriber(modid = ExampleMod.MODID, bus = Mod.EventBusSubscriber.Bus.MOD)
class Net {

    @SubscribeEvent
    public static void register(final RegisterPayloadHandlersEvent event) {
        // "1" replaces the legacy network version string; mismatched versions are rejected.
        PayloadRegistrar registrar = event.registrar("1");
        registrar.playToServer(UseWandPayload.TYPE, UseWandPayload.CODEC,
                (payload, context) -> context.enqueueWork(() -> {
                    // server logic; handlers run on the network thread until enqueued
                }));
    }

    private Net() {}
}

// Send from client: PacketDistributor.sendToServer(new UseWandPayload(x, y, z));

