@Mod.EventBusSubscriber(modid = ExampleMod.MODID, bus = Mod.EventBusSubscriber.Bus.MOD)
public class ModEntities {

    public static final DeferredRegister<EntityType<?>> ENTITY_TYPES =
            DeferredRegister.create(ForgeRegistries.ENTITY_TYPES, ExampleMod.MODID);

    public static final RegistryObject<EntityType<ForestWisp>> FOREST_WISP =
            ENTITY_TYPES.register("forest_wisp", () -> EntityType.Builder
                    .of(ForestWisp::new, MobCategory.MONSTER)
                    .sized(0.8F, 1.8F)
                    .build("forest_wisp"));

    public static void register(IEventBus modEventBus) {
        ENTITY_TYPES.register(modEventBus);
    }

    @SubscribeEvent
    public static void onAttributes(EntityAttributeCreationEvent event) {
        event.put(FOREST_WISP.get(), ForestWisp.createAttributes().build());
    }

    @SubscribeEvent
    public static void onSpawnPlacements(SpawnPlacementRegisterEvent event) {
        event.register(FOREST_WISP.get(), SpawnPlacements.Type.ON_GROUND,
                Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,
                ForestWisp::checkWispSpawnRules,
                SpawnPlacementRegisterEvent.Operation.REPLACE);
    }
}

class ForestWisp extends Monster {

    public ForestWisp(EntityType<? extends Monster> type, Level level) {
        super(type, level);
    }

    public static AttributeSupplier.Builder createAttributes() {
        return Monster.createMonsterAttributes()
                .add(Attributes.MAX_HEALTH, 24.0D)
                .add(Attributes.MOVEMENT_SPEED, 0.28D);
    }

    public static boolean checkWispSpawnRules(EntityType<? extends Monster> type,
                                              LevelAccessor level, MobSpawnType reason,
                                              BlockPos pos, RandomSource random) {
        return pos.getY() >= 40
                && Monster.checkMonsterSpawnRules(type, level, reason, pos, random);
    }
}

