package com.example.taskmod;

import java.util.function.Supplier;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.server.level.ServerPlayer;
import net.minecraftforge.network.NetworkEvent;

public class UpdateEnergyPacket {
    private final int energy;

    public UpdateEnergyPacket(int energy) {
        this.energy = energy;
    }

    public int energy() {
        return energy;
    }

    public static void encode(UpdateEnergyPacket msg, FriendlyByteBuf buf) {
        buf.writeVarInt(msg.energy);
    }

    public static UpdateEnergyPacket decode(FriendlyByteBuf buf) {
        return new UpdateEnergyPacket(buf.readVarInt());
    }

    public static void handle(UpdateEnergyPacket msg, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            ServerPlayer sender = ctx.get().getSender();
            if (sender != null) {
                sender.getFoodData().setFoodLevel(Math.max(1, msg.energy() % 20));
            }
        });
        ctx.get().setPacketHandled(true);
    }
}

