package com.example.taskmod;

import net.minecraft.world.entity.player.Player;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid = "taskmod", bus = Mod.EventBusSubscriber.Bus.FORGE)
public final class PlayerTickHandler {
    @SubscribeEvent
    public static void onPlayerTick(TickEvent.PlayerTickEvent event) {
        if (event.phase != TickEvent.Phase.END || event.side.isClient()) {
            return;
        }
        Player player = event.player;
        if (player.tickCount % 200 == 0 && player.getFoodData().getFoodLevel() < 20) {
            player.getFoodData().setFoodLevel(player.getFoodData().getFoodLevel() + 1);
        }
    }

    private PlayerTickHandler() {}
}

