package com.example.taskmod;

import com.mojang.brigadier.arguments.IntegerArgumentType;
import net.minecraft.commands.Commands;
import net.minecraft.network.chat.Component;
import net.minecraftforge.event.RegisterCommandsEvent;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid = "taskmod")
public final class TaskCommands {
    @SubscribeEvent
    public static void onRegisterCommands(RegisterCommandsEvent event) {
        event.getDispatcher().register(Commands.literal("task_energy")
                .requires(source -> source.hasPermission(2))
                .then(Commands.argument("value", IntegerArgumentType.integer(0))
                        .executes(context -> {
                            int value = IntegerArgumentType.getInteger(context, "value");
                            context.getSource().sendSuccess(
                                    () -> Component.literal("energy=" + value), false);
                            return value;
                        })));
    }

    @SubscribeEvent
    public static void onRightClickBlock(PlayerInteractEvent.RightClickBlock event) {
        if (event.getLevel().isClientSide()) {
            return;
        }
        event.getEntity().displayClientMessage(
                Component.literal("clicked " + event.getPos().toShortString()), true);
    }

    private TaskCommands() {}
}

