package com.example.taskmod;

import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

public class ChargerBlockEntity extends BlockEntity {
    private int storedEnergy;

    public ChargerBlockEntity(BlockPos pos, BlockState state) {
        super(ModBlockEntities.CHARGER.get(), pos, state);
    }

    public int getStoredEnergy() {
        return storedEnergy;
    }

    public void setStoredEnergy(int value) {
        this.storedEnergy = Math.max(0, value);
    }

    @Override
    public void load(CompoundTag tag) {
        super.load(tag);
        storedEnergy = tag.getInt("StoredEnergy");
    }

    @Override
    protected void saveAdditional(CompoundTag tag) {
        super.saveAdditional(tag);
        tag.putInt("StoredEnergy", storedEnergy);
    }
}

